on conflict (code) do update set
  name = excluded.name,
  sort_order = excluded.sort_order,
  metadata = excluded.metadata,
  updated_at = now();

select id from territories where code in ('pnw-west','pnw-east','norcal-coastal','norcal-inland','ca-central-la-north','la-metro-oc','ie-san-diego')
on conflict (territory_id) do nothing;

values (
  'a1000000-0000-4000-8000-000000000001',
  'Staff-approved Cascades / CA sales corridors (Census county FIPS 2024; LA ZIP partition v1)',
  '2026-08-22'
)
on conflict (id) do update set source = excluded.source, effective_date = excluded.effective_date;

delete from territory_geography_memberships where seed_batch_id = 'a1000000-0000-4000-8000-000000000001';


do $$
declare
  v_wa int;
  v_or int;
  v_ca int;
  v_la_county int;
  v_la_zip int;
  v_ops int;
begin
  select count(*) into v_ops from operational_territories;
  if v_ops <> 7 then raise exception 'expected 7 operational_territories, got %', v_ops; end if;

  select count(*) into v_wa from territory_geography_memberships where kind = 'county' and state_code = 'WA';
  if v_wa <> 39 then raise exception 'WA county coverage failed: %', v_wa; end if;

  select count(*) into v_or from territory_geography_memberships where kind = 'county' and state_code = 'OR';
  if v_or <> 36 then raise exception 'OR county coverage failed: %', v_or; end if;

  select count(*) into v_ca from territory_geography_memberships where kind = 'county' and state_code = 'CA';
  if v_ca <> 57 then raise exception 'CA county coverage (ex-LA) failed: %', v_ca; end if;

  select count(*) into v_la_county from territory_geography_memberships
    where kind = 'county' and county_fips = '06037';
  if v_la_county <> 0 then raise exception 'LA county must have zero county memberships'; end if;

  select count(*) into v_la_zip from territory_geography_memberships where kind = 'zip' and state_code = 'CA';
  if v_la_zip <> 258 then raise exception 'LA ZIP coverage failed: %', v_la_zip; end if;

  if not exists (
    select 1 from territory_geography_memberships m
    join territories t on t.id = m.territory_id
    where m.kind = 'county' and m.county_fips = '06053' and t.code = 'norcal-coastal'
  ) then raise exception 'Monterey lock failed'; end if;
  if not exists (
    select 1 from territory_geography_memberships m
    join territories t on t.id = m.territory_id
    where m.kind = 'county' and m.county_fips = '06019' and t.code = 'norcal-inland'
  ) then raise exception 'Fresno lock failed'; end if;
  if not exists (
    select 1 from territory_geography_memberships m
    join territories t on t.id = m.territory_id
    where m.kind = 'county' and m.county_fips = '06029' and t.code = 'ie-san-diego'
  ) then raise exception 'Kern lock failed'; end if;
end
$$;
